from pathlib import Path
script=r'''
const $=s=>document.querySelector(s),canvas=$('#c');
const scene=new THREE.Scene();scene.background=new THREE.Color('#b7d3de');scene.fog=new THREE.Fog('#b7d3de',500,1300);
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;
const camera=new THREE.PerspectiveCamera(45,1,.5,2200);scene.add(new THREE.HemisphereLight('#e5f1ff','#81735b',2));let sun=new THREE.DirectionalLight('#fff1da',3.3);sun.position.set(-220,340,-170);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-400,right:400,top:350,bottom:-350,near:1,far:950});sun.shadow.bias=-.0004;scene.add(sun);
const mat=(c,rough=0.85)=>new THREE.MeshStandardMaterial({color:c,roughness:rough});const asphalt=mat('#44494b'),concrete=mat('#aaa99f'),white=mat('#e7dfc9'),glass=mat('#56717b',.25),rubber=mat('#232629'),khaki=mat('#9c8962');
function mesh(geo,m,x,y,z,parent=scene){let o=new THREE.Mesh(geo,m);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o}
function box(x,y,z,w,h,d,m,parent=scene){return mesh(new THREE.BoxGeometry(w,h,d),m,x,y,z,parent)}
function cyl(x,y,z,r,h,m,parent=scene){return mesh(new THREE.CylinderGeometry(r,r,h,12),m,x,y,z,parent)}
function pt(u,v,y=0){return new THREE.Vector3((u-.5)*600,y,(v-.5)*450)}
function beam(a,b,width,height,m){let mid=a.clone().add(b).multiplyScalar(.5),len=a.distanceTo(b);let o=box(mid.x,mid.y,mid.z,width,height,len,m);o.quaternion.setFromUnitVectors(new THREE.Vector3(0,0,1),b.clone().sub(a).normalize());return o}
function road(points,w=5,y=.12,material=asphalt){for(let i=1;i<points.length;i++)beam(pt(...points[i-1],y),pt(...points[i],y),w,.22,material)}
function dashed(points,y=.28){for(let i=1;i<points.length;i++){let a=pt(...points[i-1],y),b=pt(...points[i],y),len=a.distanceTo(b);for(let k=0;k<len;k+=7){beam(a.clone().lerp(b,k/len),a.clone().lerp(b,Math.min((k+3)/len,1)),.19,.03,white)}}}
function sign(text,u,v,y=8){let cv=document.createElement('canvas');cv.width=512;cv.height=80;let c=cv.getContext('2d');c.fillStyle='#173e46';c.fillRect(0,0,512,80);c.strokeStyle='#b7d0c4';c.strokeRect(4,4,504,72);c.fillStyle='white';c.textAlign='center';c.font='bold 28px Arial';c.fillText(text,256,50);let sprite=new THREE.Sprite(new THREE.SpriteMaterial({map:new THREE.CanvasTexture(cv)}));sprite.position.copy(pt(u,v,y));sprite.scale.set(30,4.7,1);scene.add(sprite)}
// Procedural grass texture.
let cv=document.createElement('canvas');cv.width=cv.height=256;let ct=cv.getContext('2d');ct.fillStyle='#89916b';ct.fillRect(0,0,256,256);let seed=17;function rand(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}for(let i=0;i<15000;i++){ct.fillStyle=rand()>.5?'#929a73':'#78835d';ct.fillRect(rand()*256,rand()*256,1,2)}let tex=new THREE.CanvasTexture(cv);tex.wrapS=tex.wrapT=THREE.RepeatWrapping;tex.repeat.set(30,30);let ground=mesh(new THREE.PlaneGeometry(1600,1300),new THREE.MeshStandardMaterial({map:tex}),0,-.15,0);ground.rotation.x=-Math.PI/2;
let highway=[[.03,.88],[.18,.82],[.36,.765],[.53,.71],[.7,.66],[.88,.606]];road(highway,16,0,concrete);road(highway,14,.15);dashed(highway);road(highway,1,.4,mat('#b7b29e'));
let roads=[[[.16,.81],[.163,.49],[.16,.3],[.4,.23],[.56,.18]],[[.16,.49],[.23,.48],[.4,.23]],[[.23,.48],[.32,.6],[.35,.6],[.35,.755]],[[.397,.72],[.397,.418],[.56,.418],[.56,.18]],[[.56,.418],[.56,.21],[.75,.21]],[[.59,.68],[.59,.515],[.66,.43],[.72,.31],[.77,.31],[.81,.61]],[[.35,.525],[.54,.525]],[[.495,.7],[.495,.42]],[[.56,.18],[.58,.1],[.77,.09]],[[.75,.1],[.77,.21],[.81,.4],[.81,.61]]];roads.forEach(r=>{road(r,6,.03,concrete);road(r,4.8,.18);dashed(r)});
const structures=new THREE.Group();scene.add(structures);
function building(u,v,w,d,h,color){let p=pt(u,v);let g=new THREE.Group();g.position.copy(p);structures.add(g);box(0,h/2,0,w,h,d,mat(color),g);box(0,h+.2,0,w+.5,.4,d+.5,concrete,g);for(let yy=2;yy<h-1;yy+=3)for(let xx=-w/2+1.4;xx<w/2-1;xx+=2.8){box(xx,yy,d/2+.02,1.3,1.5,.05,glass,g);box(xx,yy,-d/2-.02,1.3,1.5,.05,glass,g)}box(0,1.3,d/2+.06,1.3,2.6,.1,mat('#544d41'),g);if(h>6)cyl(w*.25,h+.7,0,1.2,1.4,mat('#5a6060'),g)}
for(let r=0;r<5;r++)for(let j=0;j<5;j++){if(j===3)continue;building(.411+j*.026,.26+r*.029,10,8,5+rand()*8,['#cab9a1','#d3c7b1','#adaf9e','#bfa88e'][(r+j)%4])}
for(let r=0;r<6;r++)for(let j=0;j<4;j++)building(.601+j*.027,.25+r*.027,10,6.5,5+rand()*10,['#c6bda9','#c4b39b','#b8bfb5'][(j+r)%3]);
// Covered pandal with a pitched roof.
let pandal=pt(.428,.63);box(pandal.x,.3,pandal.z,35,.6,81,concrete,structures);for(let i=0;i<9;i++)for(let dx of [-17,17])cyl(pandal.x+dx,4,pandal.z-38+i*9.5,.3,8,white,structures);
let roofgeo=new THREE.BufferGeometry();roofgeo.setAttribute('position',new THREE.Float32BufferAttribute([-18,8,-42,18,8,-42,0,14,-42,-18,8,42,0,14,42,18,8,42,-18,8,-42,0,14,-42,-18,8,42,0,14,-42,0,14,42,-18,8,42,18,8,-42,18,8,42,0,14,-42,18,8,42,0,14,42,0,14,-42],3));roofgeo.computeVertexNormals();mesh(roofgeo,new THREE.MeshStandardMaterial({color:'#e1d3bb',side:THREE.DoubleSide}),pandal.x,0,pandal.z,structures);sign('MAIN PANDAL',.428,.63,21);
building(.56,.081,52,11,7,'#c9bc9d');sign('BHODWAL MAJRI STATION',.57,.08,15);
// Railway rails, ballast and sleepers.
let ra=pt(.14,.145),rb=pt(.92,.07),rv=rb.clone().sub(ra).normalize(),rn=new THREE.Vector3(-rv.z,0,rv.x);beam(ra,rb,5,.2,mat('#8e8880'));for(let t=0;t<ra.distanceTo(rb);t+=2){let q=ra.clone().addScaledVector(rv,t);beam(q.clone().addScaledVector(rn,-2),q.clone().addScaledVector(rn,2),.28,.2,mat('#5d5346'))}for(let d of [-.8,.8])beam(ra.clone().addScaledVector(rn,d).setY(.3),rb.clone().addScaledVector(rn,d).setY(.3),.12,.2,mat('#aab0b0',.3));
// Flyover ramps, deck, parapets and paired support columns.
let fly=[[.425,.747,.2],[.48,.729,10],[.64,.678,10],[.705,.656,.2]];for(let i=1;i<fly.length;i++){let a=pt(fly[i-1][0],fly[i-1][1],fly[i-1][2]),b=pt(fly[i][0],fly[i][1],fly[i][2]);beam(a,b,11,1.5,concrete);beam(a.clone().add(new THREE.Vector3(0,.85,0)),b.clone().add(new THREE.Vector3(0,.85,0)),10,.15,asphalt);let v=b.clone().sub(a).normalize(),normal=new THREE.Vector3(-v.z,0,v.x);for(let d of [-5.25,5.25])beam(a.clone().addScaledVector(normal,d).add(new THREE.Vector3(0,1.2,0)),b.clone().addScaledVector(normal,d).add(new THREE.Vector3(0,1.2,0)),.35,1,white);let len=a.distanceTo(b);for(let t=0;t<len;t+=6)beam(a.clone().lerp(b,t/len).add(new THREE.Vector3(0,.96,0)),a.clone().lerp(b,Math.min((t+2.6)/len,1)).add(new THREE.Vector3(0,.96,0)),.18,.03,white)}
for(let i=0;i<6;i++){let q=pt(.485+i*.03,.728-i*.00955);for(let dx of [-3,3])cyl(q.x+dx,4.5,q.z,.8,9,concrete);box(q.x,8.8,q.z,10,1,3,concrete)}sign('FLYOVER / UNDERPASS',.565,.714,20);
function car(u,v,color='#dddcd2',yaw=0,bus=false){let q=pt(u,v),g=new THREE.Group();g.position.copy(q);g.rotation.y=yaw;scene.add(g);let w=bus?2.7:1.8,l=bus?8:4.2;box(0,1,0,w,1.1,l,mat(color,.4),g);box(0,1.9,-.2,w*.88,.9,l*.55,glass,g);box(0,2.4,-.2,w*.92,.12,l*.58,mat(color),g);for(let x of [-w/2,w/2])for(let z of [-l*.31,l*.31]){let wh=mesh(new THREE.CylinderGeometry(.43,.43,.28,12),rubber,x,.5,z,g);wh.rotation.z=Math.PI/2}for(let x of [-w*.33,w*.33])box(x,1,l/2+.02,.35,.25,.06,mat('#ffffd3'),g)}
for(let [name,u,v,w,d] of [['P1',.17,.64,.08,.15],['P2',.28,.54,.07,.06],['P3',.58,.12,.085,.085],['P4',.593,.562,.09,.095],['P5',.36,.815,.09,.035]]){let q=pt(u+w/2,v+d/2);box(q.x,.02,q.z,w*600,.1,d*450,mat('#b3ab96'));for(let r=0;r<3;r++)for(let j=0;j<5;j++)car(u+.008+j*w/5,v+.01+r*d/3,['#e9e9df','#737e86','#a8a394','#9a6558'][Math.floor(rand()*4)],0,name==='P2');sign(name+' PARKING',u+w/2,v+d/2,9)}
for(let i=0;i<16;i++)car(.1+i*.043,.855-i*.014,['#dbdad3','#949e9b','#c2b9a6'][i%3],-1.26);
function tree(u,v){let q=pt(u,v);cyl(q.x,2.1,q.z,.38,4.2,mat('#6f5b43'));for(let i=0;i<3;i++)mesh(new THREE.IcosahedronGeometry(2.7+i*.3,1),mat(['#637d46','#536c3c','#738748'][i]),q.x+(i-1)*1.3,5.5+i*.8,q.z)}for(let i=0;i<110;i++){let u=.09+rand()*.82,v=.1+rand()*.68;if(u<.14||u>.85||v<.14)tree(u,v)}
for(let i=0;i<20;i++){let u=.17+i*.032,v=.828-i*.01,q=pt(u,v);cyl(q.x,5,q.z,.12,10,concrete);box(q.x+.7,10,q.z,1.5,.2,.5,white)}
for(let [t,u,v] of [['GATE 1',.357,.75],['GATE 2',.495,.70],['GATE 3',.58,.68]]){let q=pt(u,v);box(q.x-4,3,q.z,.35,6,.35,white);box(q.x+4,3,q.z,.35,6,.35,white);box(q.x,6,q.z,8.6,.6,.5,mat('#316572'));sign(t,u,v,8)}
const colors={officer:'#3a99e8',barricade:'#e9b139',traffic:'#a49adf',medical:'#e9687e',command:'#45bfa5',cctv:'#cdd8e1',water:'#60c9e8',access:'#92c986'};const names={officer:'Police officers',barricade:'Barricades',traffic:'Traffic posts',medical:'Medical points',command:'Command posts',cctv:'CCTV',water:'Water points',access:'Emergency access'};
let defaults=[{type:'officer',x:.357,y:.748,label:'Gate 1',qty:4},{type:'officer',x:.493,y:.695,label:'Gate 2',qty:4},{type:'officer',x:.578,y:.677,label:'Gate 3',qty:4},{type:'barricade',x:.346,y:.72,label:'Example barricade',qty:3},{type:'traffic',x:.166,y:.491,label:'Traffic post',qty:2},{type:'medical',x:.459,y:.664,label:'Medical point',qty:1}],items=structuredClone(defaults),selected=-1,placing=false,resources=new THREE.Group();scene.add(resources);try{let old=JSON.parse(localStorage.getItem('ebandobast-v1'));if(old)items=old}catch(e){}
function officer(g,x,z){for(let dx of [-.2,.2])box(x+dx,.55,z,.22,1.1,.25,khaki,g);box(x,1.45,z,.7,.8,.4,khaki,g);mesh(new THREE.SphereGeometry(.23,10,8),mat('#b88e68'),x,2.1,z,g);cyl(x,2.3,z,.28,.12,khaki,g);for(let dx of [-.48,.48])box(x+dx,1.4,z,.18,.75,.22,khaki,g);box(x,1.1,z,.74,.09,.43,rubber,g)}
function rebuild(){resources.clear();items.forEach((it,i)=>{let g=new THREE.Group();g.position.copy(pt(it.x,it.y));g.userData.index=i;resources.add(g);if(it.type==='officer'||it.type==='traffic'){for(let n=0;n<Math.min(it.qty,12);n++)officer(g,(n%4)*1.3,Math.floor(n/4)*1.5)}else if(it.type==='barricade'){for(let n=0;n<Math.min(it.qty,8);n++){let x=n*3.3;box(x,1.2,0,3,.8,.15,mat('#e7ae26'),g);for(let j=0;j<5;j++)box(x-1.2+j*.6,1.2,.09,.22,.8,.04,rubber,g);for(let dx of [-1.2,1.2]){box(x+dx,.7,0,.1,1.4,.1,rubber,g);box(x+dx,.05,0,.5,.1,1,rubber,g)}}}else if(it.type==='cctv'){cyl(0,3,0,.12,6,concrete,g);box(.4,6,0,1,.4,.4,white,g)}else{box(0,1.7,0,4,3.4,4,mat(colors[it.type]),g);box(0,3.5,0,4.6,.25,4.6,white,g);if(it.type==='medical'){box(0,2,2.03,1.5,.35,.05,white,g);box(0,2,2.05,.35,1.5,.05,white,g)}}let ring=mesh(new THREE.RingGeometry(2.5,2.7,32),new THREE.MeshBasicMaterial({color:i===selected?'#ffffff':colors[it.type],side:THREE.DoubleSide}),0,.2,0,g);ring.rotation.x=-Math.PI/2;g.traverse(o=>o.userData.index=i)});try{localStorage.setItem('ebandobast-v1',JSON.stringify(items))}catch(e){}$('#counts').innerHTML=Object.keys(names).map(k=>`<div>${names[k]} <b style="float:right">${items.filter(i=>i.type===k).reduce((a,b)=>a+b.qty,0)}</b></div>`).join('');let it=items[selected];$('#selected').innerHTML=it?'<label>Label<input id="label"></label><label>Quantity<input id="qty" type="number" min="1" max="1000"></label><button id="move">Move selected</button><button id="delete">Delete selected</button>':'Click a resource to edit.';if(it){$('#label').value=it.label;$('#qty').value=it.qty;$('#label').onchange=e=>{it.label=e.target.value;rebuild()};$('#qty').onchange=e=>{it.qty=Math.max(1,Math.min(1000,+e.target.value||1));rebuild()};$('#delete').onclick=()=>{items.splice(selected,1);selected=-1;rebuild()};$('#move').onclick=()=>{placing='move';$('#hint').textContent='Click the new position'}}}
let angle=-.25,elevation=.85,distance=480,target=new THREE.Vector3(0,0,25),tour=false,drag=null;const ray=new THREE.Raycaster(),mouse=new THREE.Vector2();function resize(){renderer.setSize(canvas.clientWidth,canvas.clientHeight,false);camera.aspect=canvas.clientWidth/canvas.clientHeight;camera.updateProjectionMatrix()}window.onresize=resize;
function animate(){requestAnimationFrame(animate);if(tour)angle+=.001;camera.position.set(target.x+Math.sin(angle)*Math.cos(elevation)*distance,target.y+Math.sin(elevation)*distance,target.z+Math.cos(angle)*Math.cos(elevation)*distance);camera.lookAt(target);renderer.render(scene,camera)}
canvas.oncontextmenu=e=>e.preventDefault();canvas.onpointerdown=e=>{drag={x:e.offsetX,y:e.offsetY,a:angle,b:elevation,tx:target.x,tz:target.z,button:e.button,moved:false};canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(!drag)return;let dx=e.offsetX-drag.x,dy=e.offsetY-drag.y;if(Math.hypot(dx,dy)>4)drag.moved=true;if(drag.button===2){target.x=drag.tx-dx*distance/700;target.z=drag.tz-dy*distance/700}else{angle=drag.a-dx*.006;elevation=Math.max(.06,Math.min(1.55,drag.b+dy*.004))}};canvas.onpointerup=e=>{if(drag&&!drag.moved){mouse.set(e.offsetX/canvas.clientWidth*2-1,-e.offsetY/canvas.clientHeight*2+1);ray.setFromCamera(mouse,camera);if(placing){let hit=ray.intersectObject(ground)[0];if(hit){let x=hit.point.x/600+.5,y=hit.point.z/450+.5;if(x>=0&&x<=1&&y>=0&&y<=1){if(placing==='move'){items[selected].x=x;items[selected].y=y}else{items.push({type:$('#type').value,x,y,label:names[$('#type').value],qty:1});selected=items.length-1}placing=false;rebuild()}}}else{let hit=ray.intersectObjects(resources.children,true)[0];selected=hit?hit.object.userData.index:-1;rebuild()}}drag=null};canvas.onwheel=e=>{e.preventDefault();distance=Math.max(25,Math.min(1000,distance+e.deltaY*.3))};
$('#iso').onclick=()=>{distance=480;elevation=.85;angle=-.25;target.set(0,0,25)};$('#top').onclick=()=>{elevation=1.55;angle=0;distance=510};$('#yaw').oninput=e=>angle=+e.target.value*Math.PI/180;$('#tilt').oninput=e=>elevation=Math.max(.08,(90-+e.target.value)*Math.PI/180);$('#zoom').oninput=e=>distance=500*90/+e.target.value;$('#land').onchange=e=>structures.visible=e.target.checked;$('#scanToggle').parentElement.style.display='none';$('#place').onclick=()=>{placing=true;$('#hint').textContent='Click ground to place selected resource'};
function download(blob,name){let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000)}$('#save').onclick=()=>download(new Blob([JSON.stringify({version:2,items},null,2)],{type:'application/json'}),'e-bandobast-deployment.json');$('#load').onclick=()=>$('#file').click();$('#file').onchange=async e=>{try{let d=JSON.parse(await e.target.files[0].text());if(!Array.isArray(d.items)||d.items.length>500||d.items.some(i=>!colors[i.type]||!Number.isFinite(i.x)||!Number.isFinite(i.y)||i.x<0||i.x>1||i.y<0||i.y>1||!Number.isInteger(i.qty)||i.qty<1||i.qty>1000))throw Error();items=d.items;selected=-1;rebuild()}catch(e){$('#status').textContent='Invalid deployment file'}};$('#png').onclick=()=>{renderer.render(scene,camera);canvas.toBlob(b=>download(b,'e-bandobast-realistic-view.png'))};$('#reset').onclick=()=>{if(confirm('Restore example deployment?')){items=structuredClone(defaults);selected=-1;rebuild()}};$('#obj').textContent='Download current 3D geometry OBJ';$('#obj').onclick=()=>{let lines=['# E-Bandobast schematic. Units approximate metres.'],offset=0;scene.updateMatrixWorld(true);scene.traverse(o=>{if(!o.isMesh||o===ground)return;let g=o.geometry,p=g.attributes.position,idx=g.index;if(!p)return;lines.push('o object_'+o.id);let v=new THREE.Vector3();for(let i=0;i<p.count;i++){v.fromBufferAttribute(p,i).applyMatrix4(o.matrixWorld);lines.push(`v ${v.x.toFixed(3)} ${v.y.toFixed(3)} ${v.z.toFixed(3)}`)}let count=idx?idx.count:p.count;for(let i=0;i<count;i+=3)lines.push('f '+[0,1,2].map(j=>offset+(idx?idx.getX(i+j):i+j)+1).join(' '));offset+=p.count});download(new Blob([lines.join('\n')]),'e-bandobast-detailed-model.obj')};let btn=document.createElement('button');btn.textContent='▶ Fly around site';btn.onclick=()=>{tour=!tour;btn.textContent=tour?'■ Stop fly-through':'▶ Fly around site'};$('#iso').parentElement.after(btn);let low=document.createElement('button');low.textContent='Street-level view';low.onclick=()=>{target.set(0,2,80);distance=90;elevation=.12;angle=-.4};btn.after(low);$('#hint').textContent='Drag: look around · Right-drag: pan · Wheel: zoom · Click: select';rebuild();resize();animate();
'''
Path('work/realistic.js').write_text(script,encoding='utf8')
print('renderer source ready')
